using System.Drawing.Imaging;

namespace Clauderoo.Tray;

/// <summary>Which variant of the clauderoo mark to show. Badge precedence is Error, then Warning, then Running.</summary>
internal enum AppIconState
{
    Normal,
    Warning,
    Error,
    Running,
    /// <summary>Monochrome outline, drawn in <see cref="SystemColors.WindowText"/>.</summary>
    HighContrast,
}

/// <summary>
/// Loads the embedded multi-size icons generated by <c>tools/IconGen</c> (<c>Icons/*.ico</c>).
/// The caller owns (and disposes) the returned <see cref="Icon"/>.
/// </summary>
internal static class AppIcons
{
    /// <summary>
    /// The frame that matches <paramref name="size"/> exactly (16, 20, 24, 32, 40, 48 or 64), or the closest one.
    /// For the tray pass <see cref="SystemInformation.SmallIconSize"/>.
    /// </summary>
    public static Icon Load(AppIconState state, Size size)
    {
        using var stream = Open(state);
        return new Icon(stream, size);
    }

    /// <summary>The whole multi-size icon, for <see cref="Form.Icon"/> (WinForms picks the title-bar and taskbar frames).</summary>
    public static Icon Load(AppIconState state)
    {
        using var stream = Open(state);
        return new Icon(stream);
    }

    static string ResourceName(AppIconState state) => "Clauderoo.Tray.Icons." + state switch
    {
        AppIconState.Warning => "state-warning.ico",
        AppIconState.Error => "state-error.ico",
        AppIconState.Running => "state-running.ico",
        AppIconState.HighContrast => "app-hc.ico",
        _ => "app.ico",
    };

    static Stream Open(AppIconState state)
    {
        var name = ResourceName(state);
        var stream = typeof(AppIcons).Assembly.GetManifestResourceStream(name)
            ?? throw new InvalidOperationException($"Embedded icon '{name}' is missing.");
        if (state != AppIconState.HighContrast) return stream;

        // app-hc.ico is drawn in black; recolour it to the theme's text colour (white on High Contrast Black, etc.).
        var ink = SystemColors.WindowText;
        if (ink.R == 0 && ink.G == 0 && ink.B == 0) return stream;
        using (stream)
        using (var copy = new MemoryStream())
        {
            stream.CopyTo(copy);
            return new MemoryStream(Tint(copy.ToArray(), ink));
        }
    }

    /// <summary>Replaces the colour of every pixel with <paramref name="ink"/>, keeping its alpha.</summary>
    static byte[] Tint(byte[] ico, Color ink)
    {
        var frames = new List<IcoFile.Frame>();
        foreach (var frame in IcoFile.Read(ico))
        {
            using var bmp = new Bitmap(new MemoryStream(frame.Data));
            using var argb = bmp.Clone(new Rectangle(0, 0, bmp.Width, bmp.Height), PixelFormat.Format32bppArgb);
            var data = argb.LockBits(new Rectangle(0, 0, argb.Width, argb.Height), ImageLockMode.ReadWrite, PixelFormat.Format32bppArgb);
            try
            {
                var pixels = new int[data.Stride / 4 * data.Height];
                System.Runtime.InteropServices.Marshal.Copy(data.Scan0, pixels, 0, pixels.Length);
                var rgb = ink.ToArgb() & 0x00FFFFFF;
                for (var i = 0; i < pixels.Length; i++) pixels[i] = (pixels[i] & unchecked((int)0xFF000000)) | rgb;
                System.Runtime.InteropServices.Marshal.Copy(pixels, 0, data.Scan0, pixels.Length);
            }
            finally
            {
                argb.UnlockBits(data);
            }
            using var png = new MemoryStream();
            argb.Save(png, ImageFormat.Png);
            frames.Add(frame with { Data = png.ToArray() });
        }
        using var output = new MemoryStream();
        IcoFile.Write(output, frames);
        return output.ToArray();
    }
}
